import{z as n,x as B,o as l,c as m,q as p,j as E,D as r,d as t,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"激活尺度漂移","description":"","frontmatter":{"title":"激活尺度漂移","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-scale-drift.md","filePath":"llm/activation-scale-drift.md","lastUpdated":1791063341000}'),d={name:"llm/activation-scale-drift.md"};function A(N,a,L,c,F,u){const o=B("Mermaid");return l(),m("div",null,[a[2]||(a[2]=p('<h1 id="激活尺度漂移" tabindex="-1">激活尺度漂移 <a class="header-anchor" href="#激活尺度漂移" aria-label="Permalink to &quot;激活尺度漂移&quot;">​</a></h1><div class="epigraph"><p>残差公路上的未归一化和可以随层、随时间变大；层归一化只钉进子层的那一截，并不自动钉住总线本身。</p><footer>—— 残差累加见 He et al., CVPR 2016；Transformer 中 LN 位置见 Xiong et al., 2020；对角增益见 Touvron et al., LayerScale, ICCV 2021</footer></div><p><a href="/llm/grad-norm-monitoring">上一课</a>监控的是反向。缺口是前向：<a href="/llm/residual-stream">残差流</a> 在 Pre-LN 下是 \\(x\\leftarrow x+F(\\mathrm{LN}(x))\\)，主干 \\(x\\) 不被 LN 重标。深度缩放只约束第 0 step 的 \\(\\mathrm{Var}(F)\\)；训练中 \\(F\\) 学会输出更大的增量，\\(\\|x\\|\\) 随层号与 step 涨。这会抬高注意力的 \\(q,k\\)（若无 QK-Norm）、抬高 FFN 中间激活、并在最后一层进入输出头前把动态范围交给一个 \\(\\gamma\\)。本课写激活传感器，以及 LayerScale / 最后一层 LN 作为结构阀，不重写 <a href="/llm/rmsnorm">RMSNorm</a> 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LN / RMSNorm 使 \\(F\\) 的输入 RMS 约为 1。\\(F\\) 仍可输出 RMS 为 10 的增量。加回主干后，下一层的 LN 再次把<strong>分支输入</strong>拉回，但主干范数已经变了。深度方向：底层 \\(\\|x\\|\\) 小、顶层大，形成「残差流放大」。时间方向：同一层的 \\(\\|x\\|\\) 随 CE 下降而涨。两者都让半精度与注意力 logits 承压，而梯度范数可以仍正常——因为 LN 的雅可比把 \\(F\\) 内部梯度按输入尺度除过了。<span class="marginnote">常见误区：看到 loss 曲线和梯度范数都正常，就断定训练健康。这一课的要点恰好相反——LN 会把分支内部的梯度&quot;除干净&quot;，所以反向看起来风平浪静，前向的总线范数却可能已经悄悄翻了几倍，直到半精度溢出或注意力 logits 发尖才爆雷。</span></p><p>Post-LN 每层把加法后的 \\(x\\) 钉回，漂移改道到 LN 的内部统计与雅可比，Xiong 等人指出这使深层更难训。本课以当代默认 Pre-LN 为主，把 Post-LN 的「看起来没漂移」当成另一种病，留给下一课 warmup。</p><p><span class="marginnote">只打印 LN <strong>之后</strong>的激活，会得出「尺度很稳」的假象。传感器应打在残差加法之后、下一层 LN 之前，即总线本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对若干层记录：残差加法后的 RMS 中位数、FFN 中间激活的 max、以及最后一层进入 lm_head 前的 RMS。与注意力 row-max、LSE 同一 step 对齐。若顶层 RMS 相对底层持续指数涨，先检查是否忘了残差 dropout 的 inverted 缩放，再检查 \\(F\\) 输出投影是否被学习率放飞。</p><p>结构阀：</p><ul><li><strong>最终 LN。</strong> Pre-LN 解码器在栈顶再做一次归一化再进输出头，避免把总线范数直接乘进 \\(W_{\\mathrm{out}}\\)。这是惯例，不是可选项。</li><li><strong>LayerScale。</strong> \\(x\\leftarrow x+\\mathrm{diag}(\\alpha)F(\\cdot)\\)，\\(\\alpha\\) 起步接近 0 或很小，训练中学习每通道增益。Touvron 等人在深 ViT 上用它稳定深度方向的增量。</li><li><strong>QK-Norm / cap。</strong> 管的是注意力内部，不降低总线 RMS；总线仍要单独记。</li></ul><p><span class="marginnote">给个数字感受一下：若总线 RMS 从底层 1 涨到顶层 16（每层只乘 1.2，20 层就够），fp16 的最大值约 65504，再乘上输出头权重后离溢出只剩不到三倍余量；同时注意力 logits 随尺度平方放大，softmax 会变得极尖，模型几乎&quot;只看一个 token&quot;。这就是为什么要在加法之后盯着分位数，而不是只看 loss。</span></p><p>不要用「把全局梯度 clip 再紧一点」当激活漂移的对策：clip 不缩小 \\(x\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RMSNorm 的反向含 \\(1/\\mathrm{RMS}\\) 因子。主干 \\(x\\) 变大时，进 \\(F\\) 的分支仍被归一化，但 LN 相对 \\(x\\) 的梯度分配改变，\\(\\gamma\\) 承担更多「读写总线尺度」的工作。\\(\\gamma\\) 与嵌入、输出头一起放大，就是上一课 LSE 发散的一条路径。权重衰减若豁免 \\(\\gamma\\)（后课），这条路径更畅通。</p><p>LayerScale 把增量先缩小，类似深度缩放的可学习版，但发生在整个训练期而不只是初始化。它与 drop-path 可同时出现在视觉配方里；语言预训练更常只留最终 LN，把 \\(\\alpha\\) 固定为 1。加 LayerScale 等于加一组新参数，coord check 要包含 \\(\\alpha\\) 的幅度。</p>',16)),(l(),E(i,null,{default:r(()=>[s(o,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%90%8C%E4%B8%80%E8%BE%93%E5%85%A5%20x%22%5D%20--%3E%20PRE%5B%22Pre-LN%EF%BC%9ALN%20%E5%8F%AA%E5%9C%A8%E5%88%86%E6%94%AF%E5%86%85%22%5D%0A%20%20IN%20--%3E%20POST%5B%22Post-LN%EF%BC%9ALN%20%E5%9C%A8%E5%8A%A0%E6%B3%95%E4%B9%8B%E5%90%8E%22%5D%0A%20%20PRE%20--%3E%20BUS%5B%22%E6%80%BB%E7%BA%BF%E4%B8%8D%E5%BD%92%E4%B8%80%EF%BC%8C%E6%B7%B1%E5%B1%82%20RMS%20%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20BUS%20--%3E%20FIX%5B%22%E9%9D%A0%E6%9C%80%E7%BB%88%20LN%20%E5%85%9C%E5%BA%95%E8%BF%9B%E8%BE%93%E5%87%BA%E5%A4%B4%22%5D%0A%20%20POST%20--%3E%20PIN%5B%22%E6%AF%8F%E5%B1%82%E7%9C%8B%E4%BC%BC%E9%92%89%E5%9B%9E%E5%8D%95%E4%BD%8D%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20PIN%20--%3E%20HARD%5B%22%E4%BD%86%E6%B7%B1%E5%B1%82%E6%9B%B4%E9%9A%BE%E8%AE%AD%EF%BC%8C%E7%97%85%E5%9B%A0%E8%97%8F%E5%9C%A8%20LN%20%E9%9B%85%E5%8F%AF%E6%AF%94%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=e("p",null,"本课不把激活量化（INT8 校准）写完：那是压缩课。但训练期总线 RMS 的分位数，就是以后量化的范围估计。MoE 专家内部各有自己的激活尺度，全局一个数会骗人，应按专家桶打。下一课专门处理 Post-LN 仍被使用时，为何必须把 warmup 拉长——那是 LN 雅可比而不是总线 RMS 的故事。",-1)),(l(),E(i,null,{default:r(()=>[s(o,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%B8%BB%E5%B9%B2%20x%22%5D%20--%3E%20LN%5B%22LN%20%2F%20RMS%20%E5%8F%AA%E4%BD%9C%E7%94%A8%E5%9C%A8%E5%88%86%E6%94%AF%22%5D%0A%20%20LN%20--%3E%20F%5B%22F%20%E5%8F%AF%E8%BE%93%E5%87%BA%E5%A4%A7%E5%A2%9E%E9%87%8F%22%5D%0A%20%20F%20--%3E%20ADD%5B%22x%20%2B%20F%22%5D%0A%20%20ADD%20--%3E%20X2%5B%22%E6%80%BB%E7%BA%BF%20RMS%20%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20X2%20--%3E%20TOP%5B%22%E6%9C%80%E7%BB%88%20LN%20%E5%86%8D%E9%92%89%E8%BF%9B%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[6]||(a[6]=e("ul",null,[e("li",null,"Pre-LN 钉的是进 \\(F\\) 的分支，不钉残差总线；漂移应在加法之后测。"),e("li",null,"梯度范数正常不能排除激活放大。"),e("li",null,"最终 LN 是 Pre-LN 栈的必需阀；LayerScale 是可学习的增量缩放。"),e("li",null,"对策不是把 clip 拧紧。"),e("li",null,"出处：He et al., CVPR 2016；Xiong et al., 2020；Touvron et al., ICCV 2021。")],-1))])}const f=n(d,[["render",A]]);export{S as __pageData,f as default};
